-- Operator-only, database-wide aggregates. No recipient or message content output.
-- Run against the migrated Mailloop database; see docs/storage-monitoring.md.
BEGIN READ ONLY;

SELECT
  pg_database_size(current_database()) AS database_bytes,
  pg_total_relation_size('public."Send"'::regclass) AS send_total_bytes,
  COUNT(*) AS message_count,
  COALESCE(
    SUM(octet_length(subject)::bigint + octet_length(body)::bigint),
    0
  ) AS message_content_bytes
FROM public."Send";

ROLLBACK;
